"""테스트용 가짜 spss 모듈 — 실제 IBM SPSS가 아님.

엔진 스크립트(spss_agent.engine_script)의 통신 규약·OMS 출력 수집·사전·고유값 처리를 Stata·SPSS 없이 검증하기 위함.
지원 문법(최소): CD, DATA LIST FREE, BEGIN DATA/END DATA, COMPUTE y = x*x, EXECUTE, DESCRIPTIVES, CORRELATIONS,
FREQUENCIES, SAVE OUTFILE, GET FILE(빈 자료), OMS/OMSEND(TEXT), FORCE_ERROR(오류 흉내), SLEEP(시간 초과 흉내).
"""

import math
import re
import time

_vars = []
_rows = []
_last_level = 0
_oms = {}  # tag -> (outfile, buffer)


class SpssError(Exception):
    pass


def StartSPSS():
    print("IBM SPSS (fake) noise on stdout")


def StopSPSS():
    pass


def GetLastErrorLevel():
    return _last_level


def _emit(text):
    for _tag, (_f, buf) in _oms.items():
        buf.append(text)


def _col(name):
    i = _vars.index(name)
    return [r[i] for r in _rows]


def _mean(v):
    return sum(v) / len(v)


def _sd(v):
    m = _mean(v)
    return math.sqrt(sum((x - m) ** 2 for x in v) / (len(v) - 1))


def Submit(cmds):
    global _vars, _rows, _last_level
    text = cmds if isinstance(cmds, str) else "\n".join(cmds)
    print("noise during submit")
    _last_level = 0
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        up = line.upper()
        m = re.match(r"OMS /TAG='(\w+)'.*OUTFILE='([^']+)'", line, re.I)
        if m:
            _oms[m.group(1)] = (m.group(2), [])
        elif up.startswith("OMSEND"):
            m = re.search(r"TAG='(\w+)'", line, re.I)
            if m and m.group(1) in _oms:
                f, buf = _oms.pop(m.group(1))
                with open(f, "w", encoding="utf-8-sig") as fh:
                    fh.write("\n\n".join(buf) + "\n")
        elif up.startswith("DATA LIST FREE"):
            _vars = [v for v in re.split(r"[\s/.]+", line.split("/", 1)[1]) if v]
            _rows = []
        elif up.startswith("BEGIN DATA"):
            vals = []
            i += 1
            while not lines[i].strip().upper().startswith("END DATA"):
                vals += [float(t) for t in lines[i].split()]
                i += 1
            k = len(_vars)
            _rows = [vals[j:j + k] for j in range(0, len(vals), k)]
        elif up.startswith("COMPUTE Y = X*X"):
            _vars.append("y")
            _rows = [r + [r[0] * r[0]] for r in _rows]
        elif up.startswith("DESCRIPTIVES"):
            name = re.search(r"VARIABLES=(\w+)", line, re.I).group(1)
            v = _col(name)
            _emit("Descriptive Statistics\n          N     Mean   Std. Deviation\n"
                  f"{name:<8}{len(v):>4}  {_mean(v):.2f}   {_sd(v):.3f}\nValid N (listwise) {len(v)}")
        elif up.startswith("CORRELATIONS"):
            x, y = _col("x"), _col("y")
            mx, my = _mean(x), _mean(y)
            r = sum((a - mx) * (b - my) for a, b in zip(x, y)) / math.sqrt(
                sum((a - mx) ** 2 for a in x) * sum((b - my) ** 2 for b in y))
            _emit(f"Correlations\nx  Pearson Correlation  1  {r:.3f}\ny  Pearson Correlation  {r:.3f}  1")
        elif up.startswith("FREQUENCIES"):
            name = re.search(r"VARIABLES=(\w+)", line, re.I).group(1)
            rows = ["{0}\n        Frequency  Percent  Valid Percent  Cumulative Percent".format(name)]
            for j, val in enumerate(_col(name)):
                rows.append(f"Valid {val:>6}   1   {100 / len(_rows):.1f}   {100 / len(_rows):.1f}   {100 * (j + 1) / len(_rows):.1f}")
            _emit("\n".join(rows))
        elif up.startswith("SAVE OUTFILE"):
            f = re.search(r"OUTFILE='([^']+)'", line, re.I).group(1)
            with open(f, "wb") as fh:
                fh.write(b"$FL2fake")
        elif up.startswith("GET FILE"):
            _vars, _rows = ["id", "age", "sex"], [[1, 30, 1], [2, 41, 2], [3, None, 1]]
        elif up.startswith("FORCE_ERROR"):
            _last_level = 3
            _emit("Error # 1. Command name: FORCE_ERROR")
            raise SpssError("fake error")
        elif up.startswith("SLEEP"):
            time.sleep(float(up.split()[1]))
        i += 1


def GetVariableCount():
    return len(_vars)


def GetVariableName(i):
    return _vars[i]


def GetVariableLabel(i):
    return _vars[i].upper()


def GetVariableType(i):
    return 0


def GetVariableFormat(i):
    return "F8.2"


def GetVariableMeasurementLevel(i):
    return "scale"


def GetCaseCount():
    return len(_rows)


class Cursor:
    def __init__(self, idx, accessType="r"):
        self.idx = idx

    def fetchall(self):
        return [tuple(r[i] for i in self.idx) for r in _rows]

    def close(self):
        pass
